}

void file::dup2(int fd) {
	int result = 0;
	FMT_RETRY(result, FMT_POSIX_CALL(dup2(fd_, fd)));
	if (result == -1) {
		FMT_THROW(system_error(
				errno, FMT_STRING("cannot duplicate file descriptor {} to {}"), fd_,
				fd));
	}
}

